```typescript
// Domain/ValueObjects/Money.ts
export interface Money {
  readonly amount: number;
  readonly currency: string;
}

export class MoneyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'MoneyError';
  }
}

export class InvalidAmountError extends MoneyError {
  constructor() {
    super('Amount must be a positive number');
  }
}

export class InvalidCurrencyError extends MoneyError {
  constructor() {
    super('Currency must be a non-empty string');
  }
}

export class CurrencyMismatchError extends MoneyError {
  constructor() {
    super('Cannot add money with different currencies');
  }
}

export class MoneyValueObject {
  private constructor(private readonly value: Money) {
    // Private constructor to enforce creation through factory methods
  }

  get amount(): number {
    return this.value.amount;
  }

  get currency(): string {
    return this.value.currency;
  }

  /**
   * Creates a new Money value object
   * @param amount The monetary amount (must be positive)
   * @param currency The currency code (non-empty string)
   * @returns A new Money value object
   * @throws InvalidAmountError if amount is not positive
   * @throws InvalidCurrencyError if currency is invalid
   */
  static create(amount: number, currency: string): Money {
    if (amount <= 0 || !Number.isFinite(amount)) {
      throw new InvalidAmountError();
    }

    if (!currency || typeof currency !== 'string') {
      throw new InvalidCurrencyError();
    }

    return {
      amount,
      currency
    };
  }

  /**
   * Creates a Money value object from a string representation
   * @param amountStr The amount as string
   * @param currency The currency code
   * @returns A new Money value object
   * @throws InvalidAmountError if amount is not positive
   * @throws InvalidCurrencyError if currency is invalid
   */
  static fromString(amountStr: string, currency: string): Money {
    const amount = parseFloat(amountStr);
    if (isNaN(amount)) {
      throw new InvalidAmountError();
    }
    return this.create(amount, currency);
  }

  /**
   * Adds another Money value object to this one
   * @param other The Money to add
   * @returns A new Money value object with the sum
   * @throws CurrencyMismatchError if currencies don't match
   */
  add(other: Money): Money {
    if (this.value.currency !== other.currency) {
      throw new CurrencyMismatchError();
    }

    const newAmount = this.value.amount + other.amount;
    return {
      amount: newAmount,
      currency: this.value.currency
    };
  }

  /**
   * Checks if this Money value object equals another
   * @param other The Money to compare with
   * @returns True if amounts and currencies match
   */
  equals(other: Money): boolean {
    return (
      this.value.amount === other.amount &&
      this.value.currency === other.currency
    );
  }

  /**
   * Creates a new Money value object with the same currency but zero amount
   * @returns A new zero Money value object
   */
  zero(): Money {
    return {
      amount: 0,
      currency: this.value.currency
    };
  }

  /**
   * Creates a new Money value object with the same amount but different currency
   * @param newCurrency The new currency code
   * @returns A new Money value object
   */
  withCurrency(newCurrency: string): Money {
    if (!newCurrency || typeof newCurrency !== 'string') {
      throw new InvalidCurrencyError();
    }

    return {
      amount: this.value.amount,
      currency: newCurrency
    };
  }

  /**
   * Returns a string representation of the Money value object
   * @returns Formatted string like "100.00 USD"
   */
  toString(): string {
    return `${this.value.amount.toFixed(2)} ${this.value.currency}`;
  }
}
