  ): Subscription {
    return new Subscription(
      id,
      userId,
      'active',
      startDate,
      endDate,
      plan
    );
  }

  static from(
    id: string,
    userId: string,
    status: 'active' | 'cancelled' | 'expired',
    startDate: Date,
    endDate: Date,
    plan: string
  ): Subscription {
