    const quote = Quote.price(input.id, input.lines, input.country);
    await this.quotes.save(quote);
    return quote;
  }
}
```

#### 3. Infrastructure and handler
```typescript
/** The only part of the DynamoDB DocumentClient API this adapter needs. */
interface QuoteTable {
