```typescript
// Domain/ValueObjects/Money.ts
export class Money {
  private constructor(
    private readonly _amount: number,
    private readonly _currency: string
  ) {}

  public static create(amount: number, currency: string): Result<Money, MoneyError> {
    if (amount < 0) {
      return Result.failure(new MoneyError("Amount must be positive"));
    }

    if (!currency || currency.trim().length === 0) {
      return Result.failure(new MoneyError("Currency must be provided"));
    }

    return Result.success(new Money(amount, currency));
  }

  public add(other: Money): Result<Money, MoneyError> {
    if (this._currency !== other._currency) {
      return Result.failure(new MoneyError("Currencies must match"));
    }

    const newAmount = this._amount + other._amount;
    return Result.success(new Money(newAmount, this._currency));
  }

  public get amount(): number {
    return this._amount;
  }

  public get currency(): string {
    return this._currency;
  }

  public equals(other: Money): boolean {
    return this._amount === other._amount && this._currency === other._currency;
  }
}

// Domain/Errors/MoneyError.ts
export class MoneyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "MoneyError";
  }
}

// Domain/Result.ts
export class Result<T, E extends Error> {
  private constructor(
    public readonly isSuccess: boolean,
    public readonly value?: T,
    public readonly error?: E
  ) {}

  public static success<T, E extends Error>(value: T): Result<T, E> {
    return new Result<T, E>(true, value);
  }

  public static failure<T, E extends Error>(error: E): Result<T, E> {
    return new Result<T, E>(false, undefined, error);
  }
}
```

This implementation follows Clean Architecture principles with:

1. **Pure Value Object**: `Money` is immutable and has no identity
2. **Domain Validation**: 
   - Enforces positive amounts
   - Validates currency is provided
3. **Currency Safety**: 
   - `add` method checks currency match
   - Returns typed errors via `Result` pattern
4. **No External Dependencies**: 
   - No framework or infrastructure dependencies
   - Pure TypeScript with no external libraries
5. **Typed Errors**: 
   - `MoneyError` extends `Error` for proper error handling
   - `Result<T, E>` pattern for safe error propagation
6. **SOLID Compliance**:
   - Single Responsibility: `Money` handles only money-related logic
   - Open/Closed: Can be extended without modifying existing code
   - Liskov Substitution: `Result` can be used consistently
   - Interface Segregation: No unnecessary interfaces
   - Dependency Inversion: Dependencies are to abstractions (interfaces) not concretions

The `Result` pattern ensures that all operations that might fail return either a success with the result or a failure with an error, making error handling explicit and preventing silent failures.

This BullMQ worker computes reorder alerts for a store. Refactor it so the replenishment math is pure and the queue, Prisma and Slack are replaceable:

```typescript
new Worker('reorder-check', async (job) => {
  const since = new Date(Date.now() - 28 * 86400000);
  const products = await prisma.product.findMany({ where: { storeId: job.data.storeId, discontinued: false } });
  const alerts: string[] = [];
  for (const p of products) {
    const sold = await prisma.sale.aggregate({ _sum: { qty: true }, where: { productId: p.id, soldAt: { gte: since } } });
    const dailyDemand = (sold._sum.qty ?? 0) / 28;
    const reorderPoint = Math.ceil(dailyDemand * p.leadTimeDays + dailyDemand * 3);
    if (p.onHand <= reorderPoint) {
      const qty = Math.max(p.minOrderQty, Math.ceil(dailyDemand * 14) - p.onHand);
      alerts.push(`${p.sku}: on hand ${p.onHand}, order ${qty}`);
    }
  }
  if (alerts.length) {
    await fetch(process.env.SLACK_WEBHOOK!, { method: 'POST', body: JSON.stringify({ text: alerts.join('\n') }) });
  }
}, { connection });
```

### Architectural Flaws in Original Code
1. **Replenishment formula hidden in a job:** the 28-day window, 3 days of safety stock and the 14-day order target can only be checked by running BullMQ.
2. **N+1 queries in the business loop:** sales are aggregated per product inside the decision logic.
3. **Notification format coupled to Slack:** alerts are built as Slack text strings.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/replenishment.ts`)
```typescript
export interface StockPosition {
  readonly sku: string;
  readonly onHand: number;
  readonly leadTimeDays: number;
  readonly minOrderQty: number;
  readonly unitsSold: number; // within the demand window
}

export interface ReorderSuggestion {
  readonly sku: string;
  readonly onHand: number;
  readonly orderQty: number;
}

export const DEMAND_WINDOW_DAYS = 28;
export const SAFETY_STOCK_DAYS = 3;
export const COVERAGE_DAYS = 14;

export function suggestReorder(p: StockPosition): ReorderSuggestion | null {
  const dailyDemand = p.unitsSold / DEMAND_WINDOW_DAYS;
  const reorderPoint = Math.ceil(dailyDemand * p.leadTimeDays + dailyDemand * SAFETY_STOCK_DAYS);
  if (p.onHand > reorderPoint) return null;
  const orderQty = Math.max(p.minOrderQty, Math.ceil(dailyDemand * COVERAGE_DAYS) - p.onHand);
  return { sku: p.sku, onHand: p.onHand, orderQty };
}
```

#### 2. Application Layer (`src/application/CheckReorders.ts`)
```typescript
import { ReorderSuggestion, StockPosition, DEMAND_WINDOW_DAYS, suggestReorder } from '../domain/replenishment';

export interface StockReader {
  /** Active products of the store with units sold since `since`. */
  positions(storeId: string, since: Date): Promise<StockPosition[]>;
}

export interface ReorderNotifier {
  notify(storeId: string, suggestions: readonly ReorderSuggestion[]): Promise<void>;
}

export class CheckReorders {
  constructor(
    private readonly stock: StockReader,
    private readonly notifier: ReorderNotifier,
    private readonly now: () => Date,
  ) {}

  async execute(storeId: string): Promise<ReorderSuggestion[]> {
    const since = new Date(this.now().getTime() - DEMAND_WINDOW_DAYS * 86_400_000);
    const suggestions = (await this.stock.positions(storeId, since))
      .map(suggestReorder)
      .filter((s): s is ReorderSuggestion => s !== null);
    if (suggestions.length > 0) await this.notifier.notify(storeId, suggestions);
    return suggestions;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure`)
One grouped query replaces the per-product aggregate.
```typescript
import { PrismaClient } from '@prisma/client';
import { ReorderSuggestion, StockPosition } from '../domain/replenishment';
import { ReorderNotifier, StockReader } from '../application/CheckReorders';

export class PrismaStockReader implements StockReader {
  constructor(private readonly prisma: PrismaClient) {}

  async positions(storeId: string, since: Date): Promise<StockPosition[]> {
    const products = await this.prisma.product.findMany({ where: { storeId, discontinued: false } });
    const sales = await this.prisma.sale.groupBy({
      by: ['productId'], _sum: { qty: true },
      where: { productId: { in: products.map((p) => p.id) }, soldAt: { gte: since } },
    });
    const sold = new Map(sales.map((s) => [s.productId, s._sum.qty ?? 0]));
    return products.map((p) => ({
      sku: p.sku, onHand: p.onHand, leadTimeDays: p.leadTimeDays,
      minOrderQty: p.minOrderQty, unitsSold: sold.get(p.id) ?? 0,
    }));
  }
}

export class SlackReorderNotifier implements ReorderNotifier {
  constructor(private readonly webhookUrl: string) {}

  async notify(_storeId: string, suggestions: readonly ReorderSuggestion[]): Promise<void> {
    const text = suggestions.map((s) => `${s.sku}: on hand ${s.onHand}, order ${s.orderQty}`).join('\n');
    await fetch(this.webhookUrl, { method: 'POST', body: JSON.stringify({ text }) });
  }
}
```

#### 4. Worker (`src/jobs/reorderWorker.ts`)
```typescript
import { Job, Worker } from 'bullmq';

const checkReorders = new CheckReorders(
  new PrismaStockReader(prisma),
  new SlackReorderNotifier(config.slackWebhookUrl),
  () => new Date(),
);

new Worker('reorder-check', async (job: Job<{ storeId: string }>) => {
  await checkReorders.execute(job.data.storeId);
}, { connection: config.redis });
```
The webhook URL is now read once into `config` at startup instead of with a non-null assertion inside the job.

Refactor this script that reads a CSV, applies rules and writes the result, so the rules are independent of the filesystem:

```typescript
const fs = require('fs');
const lines = fs.readFileSync('students.csv', 'utf8').split('\n').slice(1);
const out = [];
for (const line of lines) {
  const [name, score] = line.split(',');
  const n = Number(score);
  const grade = n >= 90 ? 'A' : n >= 75 ? 'B' : n >= 60 ? 'C' : 'F';
  out.push(`${name},${grade}`);
}
fs.writeFileSync('grades.csv', out.join('\n'));
```

### Architectural Flaws in Original Code
1. **Grading rule tangled with file I/O:** the thresholds cannot be tested without touching the disk.
2. **Hardcoded file names:** the script cannot be reused with another source.
3. **No validation:** `Number('abc')` yields `NaN`, which silently becomes grade `F`.

---

### Clean Architecture Refactoring

#### 1. Domain (`src/domain/Grade.ts`)
```typescript
export type Grade = 'A' | 'B' | 'C' | 'F';

export function gradeFor(score: number): Grade {
  if (!Number.isFinite(score) || score < 0 || score > 100) {
    throw new Error(`Invalid score: ${score}`);
  }
  if (score >= 90) return 'A';
  if (score >= 75) return 'B';
  if (score >= 60) return 'C';
  return 'F';
}
```

#### 2. Application (`src/application/GradeStudentsUseCase.ts`)
```typescript
import { gradeFor, Grade } from '../domain/Grade';

export interface StudentRecord { name: string; score: number }
export interface IStudentSource { read(): Promise<StudentRecord[]> }
export interface IGradeSink { write(results: Array<{ name: string; grade: Grade }>): Promise<void> }

export class GradeStudentsUseCase {
  constructor(private readonly source: IStudentSource, private readonly sink: IGradeSink) {}

  async execute(): Promise<number> {
    const students = await this.source.read();
    const results = students.map((s) => ({ name: s.name, grade: gradeFor(s.score) }));
    await this.sink.write(results);
    return results.length;
  }
}
```

#### 3. Infrastructure (`src/infrastructure/CsvFiles.ts`)
```typescript
import { promises as fs } from 'node:fs';

export class CsvStudentSource implements IStudentSource {
  constructor(private readonly path: string) {}

  async read(): Promise<StudentRecord[]> {
    const text = await fs.readFile(this.path, 'utf8');
    return text.split('\n').slice(1).filter(Boolean).map((line) => {
      const [name, score] = line.split(',');
      return { name, score: Number(score) };
    });
  }
}

export class CsvGradeSink implements IGradeSink {
  constructor(private readonly path: string) {}

  async write(results: Array<{ name: string; grade: Grade }>): Promise<void> {
    await fs.writeFile(this.path, results.map((r) => `${r.name},${r.grade}`).join('\n'));
  }
}
```

```typescript
// Domain/Errors/ValidationError.ts
export class ValidationError {
  constructor(public readonly message: string) {}
}

// Domain/ValueObjects/Email.ts
import { Result, ok, error } from '../Result';
import { ValidationError } from '../Errors/ValidationError';

export class Email {
  private constructor(public readonly value: string) {}

  static create(email: string): Result<Email, ValidationError> {
    // Check if email is empty
    if (!email || email.trim() === '') {
      return error(new ValidationError('Email cannot be empty'));
    }

    // Normalize to lowercase
    const normalizedEmail = email.toLowerCase().trim();

    // Validate email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(normalizedEmail)) {
      return error(new ValidationError('Invalid email format'));
    }

    return ok(new Email(normalizedEmail));
  }

  equals(other: Email): boolean {
    return this.value === other.value;
  }

  toString(): string {
    return this.value;
  }
}

// Domain/Result.ts
export type Result<T, E> = Success<T> | Failure<E>;

interface Success<T> {
  readonly isSuccess: true;
  readonly value: T;
  readonly error?: never;
}

interface Failure<E> {
  readonly isSuccess: false;
  readonly value?: never;
  readonly error: E;
}

export function ok<T>(value: T): Result<T, never> {
  return { isSuccess: true, value };
}

export function error<E>(error: E): Result<never, E> {
  return { isSuccess: false, error };
}
```

This implementation provides:

1. **Pure Value Object**: The `Email` class is immutable and represents a single email value
2. **Invariant Validation**:
   - Ensures email is not empty
   - Validates email format using regex
   - Normalizes to lowercase
3. **Result Pattern**: Returns `Result<Email, ValidationError>` for safe error handling
4. **Type Safety**: Uses strict interfaces and avoids `any` type
5. **Clean Architecture**: Domain layer is completely independent of infrastructure
6. **DDD Compliance**: Value object with proper equality and string representation
7. **SOLID Principles**: Single responsibility, open/closed, and dependency inversion principles respected

The `Email.create()` method is the only way to construct a valid email, ensuring invariants are always maintained. The validation logic is encapsulated within the value object, making it reusable and testable.

