// Domain/ValueObjects/Money.ts
export interface Money {
  readonly amount: number;
  readonly currency: string;
}

export class MoneyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "MoneyError";
  }
}

export class InvalidAmountError extends MoneyError {
  constructor() {
    super("Amount must be positive");
    this.name = "InvalidAmountError";
  }
}

export class CurrencyMismatchError extends MoneyError {
  constructor() {
    super("Currencies must match for addition");
    this.name = "CurrencyMismatchError";
  }
}

export class MoneyValueObject {
  private constructor(private readonly _amount: number, private readonly _currency: string) {
    if (_amount < 0) {
      throw new InvalidAmountError();
    }
  }

  static create(amount: number, currency: string): Money {
    return new MoneyValueObject(amount, currency);
  }

  get amount(): number {
    return this._amount;
  }

  get currency(): string {
    return this._currency;
  }

  add(other: Money): Money {
    if (this._currency !== other.currency) {
      throw new CurrencyMismatchError();
    }

    return new MoneyValueObject(
      this._amount + other.amount,
      this._currency
    );
  }

  equals(other: Money): boolean {
    return this._amount === other.amount && this._currency === other.currency;
  }
}
