  if (result.success) return NextResponse.json({ lateFee: result.data.lateFee });
  return result.error.kind === 'BookingNotFound'
    ? NextResponse.json({ error: 'Not found' }, { status: 404 })
    : NextResponse.json({ error: 'Class already started' }, { status: 409 });
}
