```

### Architectural Flaws in Original Code
1. **Settlement logic in the message loop:** status transitions and overpayment detection are tied to `kafkajs` callbacks.
2. **Untyped event:** the payload is `JSON.parse`d and used without validation.
3. **Silent idempotency gap:** a redelivered message is applied twice because the payment reference is never checked.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Invoice.ts`)
```typescript
import { Result } from '../shared/Result';

export type InvoiceStatus = 'open' | 'partially_paid' | 'paid' | 'void';
export type SettlementError = { kind: 'InvoiceVoid' } | { kind: 'DuplicatePayment'; ref: string };

export interface Payment { readonly ref: string; readonly amountCents: number; }

export class Invoice {
  constructor(
    readonly id: string,
    readonly totalCents: number,
    private paidCents: number,
    private currentStatus: InvoiceStatus,
    private readonly payments: Payment[],
  ) {}

  get paid(): number { return this.paidCents; }
  get status(): InvoiceStatus { return this.currentStatus; }

  /** Applies a payment and returns the overpaid amount in cents (0 if none). */
  apply(payment: Payment): Result<number, SettlementError> {
    if (this.currentStatus === 'void') return Result.fail({ kind: 'InvoiceVoid' });
    if (this.payments.some((p) => p.ref === payment.ref)) {
      return Result.fail({ kind: 'DuplicatePayment', ref: payment.ref });
    }
    this.payments.push(payment);
    this.paidCents += payment.amountCents;
    this.currentStatus = this.paidCents >= this.totalCents ? 'paid' : 'partially_paid';
    return Result.ok(Math.max(0, this.paidCents - this.totalCents));
  }
}
```

#### 2. Application Layer (`src/application/SettleInvoice.ts`)
```typescript
import { Result } from '../shared/Result';
import { Invoice, Payment, SettlementError } from '../domain/Invoice';

export type SettleError = SettlementError | { kind: 'InvoiceNotFound' };

export interface InvoiceRepository {
  findById(id: string): Promise<Invoice | null>;
  recordPayment(invoice: Invoice, payment: Payment): Promise<void>;
}

export interface RefundRequester {
  request(invoiceId: string, amountCents: number): Promise<void>;
}

export class SettleInvoice {
  constructor(private readonly invoices: InvoiceRepository, private readonly refunds: RefundRequester) {}

  async execute(invoiceId: string, payment: Payment): Promise<Result<void, SettleError>> {
    const invoice = await this.invoices.findById(invoiceId);
    if (!invoice) return Result.fail({ kind: 'InvoiceNotFound' });

    const overpaid = invoice.apply(payment);
    if (!overpaid.success) return overpaid;

    await this.invoices.recordPayment(invoice, payment);
    if (overpaid.data > 0) await this.refunds.request(invoiceId, overpaid.data);
    return Result.ok(undefined);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure`)
```typescript
import { Collection } from 'mongodb';
import { Producer } from 'kafkajs';
import { Invoice, InvoiceStatus, Payment } from '../domain/Invoice';
import { InvoiceRepository, RefundRequester } from '../application/SettleInvoice';

interface InvoiceDoc {
  _id: string; totalCents: number; paid: number; status: InvoiceStatus;
  payments: { ref: string; amount: number }[];
}

export class MongoInvoiceRepository implements InvoiceRepository {
  constructor(private readonly invoices: Collection<InvoiceDoc>) {}

  async findById(id: string): Promise<Invoice | null> {
    const doc = await this.invoices.findOne({ _id: id });
    if (!doc) return null;
    const payments = doc.payments.map((p) => ({ ref: p.ref, amountCents: p.amount }));
    return new Invoice(doc._id, doc.totalCents, doc.paid, doc.status, payments);
  }

  async recordPayment(invoice: Invoice, payment: Payment): Promise<void> {
    await this.invoices.updateOne(
      { _id: invoice.id },
      { $set: { paid: invoice.paid, status: invoice.status },
        $push: { payments: { ref: payment.ref, amount: payment.amountCents } } },
    );
  }
}

export class KafkaRefundRequester implements RefundRequester {
  constructor(private readonly producer: Producer) {}

  async request(invoiceId: string, amountCents: number): Promise<void> {
    await this.producer.send({ topic: 'refunds', messages: [{ value: JSON.stringify({ invoiceId, amountCents }) }] });
  }
}
