function toHttp(error: UploadError): [number, string] {
  switch (error.kind) {
    case 'UnsupportedType': return [415, 'Unsupported type'];
    case 'TooLarge': return [413, 'File too large'];
    case 'ClaimNotFound': return [404, 'Claim not found'];
    case 'ClaimClosed': return [409, 'Claim is closed'];
    case 'TooManyDocuments': return [409, 'Too many documents'];
  }
}

app.post('/claims/:claimId/documents', upload.single('file'), async (req, res) => {
  const file = req.file;
  if (!file) return res.status(400).json({ error: 'No file' });
  const result = await attachDocument.execute(req.params.claimId, {
    fileName: file.originalname, mimeType: file.mimetype, sizeBytes: file.size, content: file.buffer,
  });
  if (result.success) return res.status(201).json({ key: result.data });
  const [status, error] = toHttp(result.error);
  res.status(status).json({ error });
