    try {
      // Validate request
      if (!request.subscriptionId || !request.customerId) {
        return error(new SubscriptionValidationError('Invalid request parameters'));
      }

      // Get subscription from repository
      const subscription = await this.subscriptionRepository.findById(
        request.subscriptionId
      );

      if (!subscription) {
        return error(new SubscriptionValidationError('Subscription not found'));
      }

      // Validate customer ownership
      if (subscription.customerId !== request.customerId) {
        return error(new SubscriptionValidationError('Unauthorized to cancel this subscription'));
      }

      // Validate cancellation rules
      SubscriptionValidator.validateCancelSubscription(subscription);

      // Update subscription status
      const updatedSubscription = {
        ...subscription,
        status: 'cancelled' as const,
        updatedAt: request.cancelledAt
      };

      // Save updated subscription
      await this.subscriptionRepository.update(updatedSubscription);

      return ok({
        subscription: updatedSubscription,
        message: 'Subscription cancelled successfully'
      });
    } catch (err) {
      if (err instanceof SubscriptionStatusError) {
        return error(err);
      }

      if (err instanceof SubscriptionValidationError) {
        return error(err);
      }

      return error(new SubscriptionValidationError('Failed to cancel subscription'));
    }
  }
}

// Domain/Repositories/SubscriptionRepository.ts
export interface SubscriptionRepository {
  findById(id: string): Promise<Subscription | null>;
  update(subscription: Subscription): Promise<void>;
}
