// Domain/Entities/Subscription.ts
export class Subscription {
  private constructor(
    public readonly id: string,
    public readonly customerId: string,
    public readonly startDate: Date,
    public readonly endDate: Date,
    public readonly status: SubscriptionStatus,
    public readonly plan: string
  ) {}

  static create(
    id: string,
    customerId: string,
    startDate: Date,
    endDate: Date,
    plan: string
  ): Subscription {
    return new Subscription(
      id,
      customerId,
      startDate,
      endDate,
      SubscriptionStatus.Active,
      plan
    );
  }

  static from(
    id: string,
    customerId: string,
    startDate: Date,
    endDate: Date,
    status: SubscriptionStatus,
    plan: string
  ): Subscription {
    return new Subscription(id, customerId, startDate, endDate, status, plan);
  }

  isExpired(): boolean {
    return new Date() > this.endDate;
  }

  isActive(): boolean {
    return this.status === SubscriptionStatus.Active;
  }

  cancel(): Subscription {
    if (this.isExpired()) {
      throw new SubscriptionAlreadyExpiredError();
    }

    return new Subscription(
      this.id,
      this.customerId,
      this.startDate,
      this.endDate,
      SubscriptionStatus.Cancelled,
      this.plan
    );
  }
}

export enum SubscriptionStatus {
  Active = 'ACTIVE',
  Cancelled = 'CANCELLED',
  Expired = 'EXPIRED'
}

// Domain/Errors/SubscriptionErrors.ts
export class SubscriptionError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SubscriptionError';
  }
}

export class SubscriptionAlreadyExpiredError extends SubscriptionError {
  constructor() {
    super('Cannot cancel an already expired subscription');
    this.name = 'SubscriptionAlreadyExpiredError';
  }
}

// Application/UseCases/CancelSubscriptionUseCase.ts
import { Result, Ok, Err } from '../Types/Result';
import { Subscription } from '../../Domain/Entities/Subscription';
import { SubscriptionError, SubscriptionAlreadyExpiredError } from '../../Domain/Errors/SubscriptionErrors';

export interface CancelSubscriptionUseCase {
  execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionError>>;
}

export class CancelSubscriptionUseCaseImpl implements CancelSubscriptionUseCase {
  constructor(
    private readonly subscriptionRepository: SubscriptionRepository
  ) {}

  async execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionError>> {
    try {
      const subscription = await this.subscriptionRepository.findById(subscriptionId);

      if (!subscription) {
        return Err(new SubscriptionNotFoundError(subscriptionId));
      }

      const cancelledSubscription = subscription.cancel();

      await this.subscriptionRepository.save(cancelledSubscription);

      return Ok(cancelledSubscription);
    } catch (error) {
      if (error instanceof SubscriptionAlreadyExpiredError) {
        return Err(error);
      }
      return Err(new CancelSubscriptionFailedError());
    }
  }
}

// Domain/Errors/SubscriptionNotFoundError.ts
export class SubscriptionNotFoundError extends SubscriptionError {
  constructor(subscriptionId: string) {
    super(`Subscription with ID ${subscriptionId} not found`);
    this.name = 'SubscriptionNotFoundError';
  }
}

// Domain/Errors/CancelSubscriptionFailedError.ts
export class CancelSubscriptionFailedError extends SubscriptionError {
  constructor() {
    super('Failed to cancel subscription');
    this.name = 'CancelSubscriptionFailedError';
  }
}

// Application/Repositories/SubscriptionRepository.ts
export interface SubscriptionRepository {
  findById(id: string): Promise<Subscription | null>;
  save(subscription: Subscription): Promise<void>;
}
```

This implementation follows Clean Architecture principles with:

1. **Pure Domain Entity**: `Subscription` contains only business logic and data, with no dependencies on external frameworks
2. **Invariant Validation**: The `cancel()` method validates that subscriptions cannot be cancelled if they're already expired
3. **Result Pattern**: Use cases return `Result<Subscription, SubscriptionError>` to handle success/failure cases
4. **Typed Domain Errors**: Specific error types for different failure scenarios
5. **Dependency Rule Compliance**: Domain layer (entities, errors) has no dependencies on infrastructure or external libraries
6. **SOLID Principles**: 
   - Single Responsibility: Each class has one clear purpose
   - Open/Closed: Easy to extend with new error types
   - Liskov Substitution: Error inheritance maintains contract
   - Interface Segregation: Clear repository interface
   - Dependency Inversion: Use cases depend on abstractions

The `CancelSubscriptionUseCase` properly handles the invariant rule by checking if the subscription is expired before attempting cancellation, returning appropriate error types through the Result pattern.

Restructure this renewal job using Clean Architecture. Billing rules, Stripe and Sequelize are tangled together:

```typescript
cron.schedule('0 3 * * *', async () => {
  const due = await Subscription.findAll({
    where: { status: 'active', renewsAt: { [Op.lte]: new Date() } },
  });
  for (const sub of due) {
    try {
      await stripe.paymentIntents.create({
        amount: sub.priceCents, currency: 'usd', customer: sub.stripeCustomerId,
        payment_method: sub.defaultPaymentMethod, off_session: true, confirm: true,
      });
      const next = new Date(sub.renewsAt);
      next.setMonth(next.getMonth() + (sub.interval === 'yearly' ? 12 : 1));
      await sub.update({ renewsAt: next, failedAttempts: 0 });
    } catch (e) {
      const attempts = sub.failedAttempts + 1;
      await sub.update({ failedAttempts: attempts, status: attempts >= 3 ? 'past_due' : 'active' });
    }
  }
});
```

### Architectural Flaws in Original Code
1. **Renewal policy hidden in a cron callback:** the billing interval and the three-strike rule cannot be tested without Stripe and a database.
2. **Active Record models as domain:** `sub.update(...)` couples state changes to Sequelize.
3. **Exceptions as control flow:** any error, including a bug, is counted as a failed charge.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Subscription.ts`)
```typescript
export type BillingInterval = 'monthly' | 'yearly';
export type SubscriptionStatus = 'active' | 'past_due';

export class Subscription {
  static readonly MAX_FAILED_ATTEMPTS = 3;

  constructor(
    readonly id: string,
    readonly customerRef: string,
    readonly paymentMethodRef: string,
    readonly priceCents: number,
    readonly interval: BillingInterval,
    private renewal: Date,
    private failures: number,
    private state: SubscriptionStatus,
  ) {}

  get renewsAt(): Date { return this.renewal; }
  get failedAttempts(): number { return this.failures; }
  get status(): SubscriptionStatus { return this.state; }

  renewed(): void {
    const next = new Date(this.renewal);
    next.setMonth(next.getMonth() + (this.interval === 'yearly' ? 12 : 1));
    this.renewal = next;
    this.failures = 0;
  }

  chargeFailed(): void {
    this.failures += 1;
    if (this.failures >= Subscription.MAX_FAILED_ATTEMPTS) this.state = 'past_due';
  }
}
```

#### 2. Application Layer (`src/application/RenewDueSubscriptions.ts`)
```typescript
import { Result } from '../shared/Result';
import { Subscription } from '../domain/Subscription';

export type ChargeError = { kind: 'Declined'; reason: string };

export interface SubscriptionRepository {
  findDue(asOf: Date): Promise<Subscription[]>;
  save(subscription: Subscription): Promise<void>;
}

export interface PaymentProcessor {
  charge(customerRef: string, paymentMethodRef: string, amountCents: number): Promise<Result<void, ChargeError>>;
}

export class RenewDueSubscriptions {
  constructor(
    private readonly subscriptions: SubscriptionRepository,
    private readonly payments: PaymentProcessor,
    private readonly now: () => Date,
  ) {}

  async execute(): Promise<{ renewed: number; failed: number }> {
    let renewed = 0;
    let failed = 0;
    for (const sub of await this.subscriptions.findDue(this.now())) {
      const charge = await this.payments.charge(sub.customerRef, sub.paymentMethodRef, sub.priceCents);
      if (charge.success) { sub.renewed(); renewed++; } else { sub.chargeFailed(); failed++; }
      await this.subscriptions.save(sub);
    }
    return { renewed, failed };
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/StripePaymentProcessor.ts`)
```typescript
import Stripe from 'stripe';
import { Result } from '../shared/Result';
import { ChargeError, PaymentProcessor } from '../application/RenewDueSubscriptions';

function isCardDecline(error: unknown): error is { type: 'StripeCardError'; message: string } {
  return typeof error === 'object' && error !== null && (error as { type?: unknown }).type === 'StripeCardError';
}

export class StripePaymentProcessor implements PaymentProcessor {
  constructor(private readonly stripe: Stripe) {}

  async charge(customerRef: string, paymentMethodRef: string, amountCents: number): Promise<Result<void, ChargeError>> {
    try {
      await this.stripe.paymentIntents.create({
        amount: amountCents, currency: 'usd', customer: customerRef,
        payment_method: paymentMethodRef,
        off_session: true, confirm: true,
      });
      return Result.ok(undefined);
    } catch (error) {
      if (isCardDecline(error)) {
        return Result.fail({ kind: 'Declined', reason: error.message });
      }
      throw error; // infrastructure failures are not counted as declined charges
    }
  }
}
```
A `SequelizeSubscriptionRepository` maps rows to `Subscription` in `findDue` (`status: 'active'`, `renewsAt <= asOf`) and writes `renewsAt`, `failedAttempts` and `status` back in `save`.

#### 4. Scheduler (`src/infrastructure/jobs.ts`)
```typescript
cron.schedule('0 3 * * *', async () => {
  const { renewed, failed } = await renewDueSubscriptions.execute();
  logger.info(`renewals: ${renewed} ok, ${failed} failed`);
});
```

