This Node.js script computes weekly pay. Move it to a layered TypeScript design where the pay rules don't touch the filesystem:

```javascript
const fs = require('fs');

const shifts = JSON.parse(fs.readFileSync('./shifts.json', 'utf8'));
const rates = JSON.parse(fs.readFileSync('./rates.json', 'utf8'));
const byEmployee = {};
for (const s of shifts) {
  const hours = (new Date(s.end) - new Date(s.start)) / 3600000;
  byEmployee[s.employeeId] = (byEmployee[s.employeeId] || 0) + hours;
}
const lines = ['employee,regular,overtime,gross'];
for (const id of Object.keys(byEmployee)) {
  const total = byEmployee[id];
  const regular = Math.min(total, 40);
  const overtime = Math.max(0, total - 40);
  const gross = regular * rates[id] + overtime * rates[id] * 1.5;
  lines.push(`${id},${regular.toFixed(2)},${overtime.toFixed(2)},${gross.toFixed(2)}`);
}
fs.writeFileSync('./payroll.csv', lines.join('\n'));
```

### Architectural Flaws in Original Code
1. **Pay rules mixed with I/O:** the 40-hour threshold and the 1.5× overtime multiplier sit between `readFileSync` and `writeFileSync`.
2. **Missing rate is silent:** an employee without a rate produces `NaN` in the CSV.
3. **Output format coupled to calculation:** CSV formatting is interleaved with the arithmetic.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/payroll.ts`)
```typescript
export interface Shift {
  readonly employeeId: string;
  readonly start: Date;
  readonly end: Date;
}

export interface PayLine {
  readonly employeeId: string;
  readonly regularHours: number;
  readonly overtimeHours: number;
  readonly gross: number;
}

export const REGULAR_WEEK_HOURS = 40;
export const OVERTIME_MULTIPLIER = 1.5;

export function hoursByEmployee(shifts: readonly Shift[]): Map<string, number> {
  const totals = new Map<string, number>();
  for (const s of shifts) {
    const hours = (s.end.getTime() - s.start.getTime()) / 3_600_000;
    totals.set(s.employeeId, (totals.get(s.employeeId) ?? 0) + hours);
  }
  return totals;
}

export function payFor(employeeId: string, hours: number, hourlyRate: number): PayLine {
  const regularHours = Math.min(hours, REGULAR_WEEK_HOURS);
  const overtimeHours = Math.max(0, hours - REGULAR_WEEK_HOURS);
  const gross = regularHours * hourlyRate + overtimeHours * hourlyRate * OVERTIME_MULTIPLIER;
  return { employeeId, regularHours, overtimeHours, gross };
}
```

#### 2. Application Layer (`src/application/RunPayroll.ts`)
```typescript
import { Result } from '../shared/Result';
import { PayLine, Shift, hoursByEmployee, payFor } from '../domain/payroll';

export type PayrollError = { kind: 'MissingRate'; employeeIds: string[] };

export interface TimesheetSource {
  shifts(): Promise<Shift[]>;
  hourlyRates(): Promise<Map<string, number>>;
}

export interface PayrollSink {
  write(lines: readonly PayLine[]): Promise<void>;
}

export class RunPayroll {
  constructor(private readonly source: TimesheetSource, private readonly sink: PayrollSink) {}

  async execute(): Promise<Result<PayLine[], PayrollError>> {
    const [shifts, rates] = await Promise.all([this.source.shifts(), this.source.hourlyRates()]);
    const totals = hoursByEmployee(shifts);

    const missing = [...totals.keys()].filter((id) => !rates.has(id));
    if (missing.length > 0) return Result.fail({ kind: 'MissingRate', employeeIds: missing });

    const lines = [...totals].map(([id, hours]) => payFor(id, hours, rates.get(id) ?? 0));
    await this.sink.write(lines);
    return Result.ok(lines);
  }
}
```
A missing rate is now an explicit error instead of `NaN` in the output.

#### 3. Infrastructure Layer (`src/infrastructure/files.ts`)
```typescript
import { readFile, writeFile } from 'node:fs/promises';
import { PayLine, Shift } from '../domain/payroll';
import { PayrollSink, TimesheetSource } from '../application/RunPayroll';

interface ShiftRecord { employeeId: string; start: string; end: string; }

export class JsonTimesheetSource implements TimesheetSource {
  constructor(private readonly shiftsPath: string, private readonly ratesPath: string) {}

  async shifts(): Promise<Shift[]> {
    const records = JSON.parse(await readFile(this.shiftsPath, 'utf8')) as ShiftRecord[];
    return records.map((r) => ({ employeeId: r.employeeId, start: new Date(r.start), end: new Date(r.end) }));
  }

  async hourlyRates(): Promise<Map<string, number>> {
    const rates = JSON.parse(await readFile(this.ratesPath, 'utf8')) as Record<string, number>;
    return new Map(Object.entries(rates));
  }
}

export class CsvPayrollSink implements PayrollSink {
  constructor(private readonly path: string) {}

  async write(lines: readonly PayLine[]): Promise<void> {
    const rows = lines.map((l) =>
      [l.employeeId, l.regularHours.toFixed(2), l.overtimeHours.toFixed(2), l.gross.toFixed(2)].join(','));
    await writeFile(this.path, ['employee,regular,overtime,gross', ...rows].join('\n'));
  }
}
```

#### 4. Composition Root (`src/main.ts`)
