  new JsonTimesheetSource('./shifts.json', './rates.json'),
  new CsvPayrollSink('./payroll.csv'),
);
const result = await payroll.execute();
if (!result.success) {
  console.error(`No hourly rate for: ${result.error.employeeIds.join(', ')}`);
  process.exitCode = 1;
}
