This release CLI decides the next version from git commits. Refactor it so the versioning rules are independent of git, yargs and the filesystem:

```typescript
const argv = yargs(hideBin(process.argv)).option('dry-run', { type: 'boolean' }).parseSync();
const git = simpleGit();
const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
const lastTag = (await git.tags()).latest ?? 'v0.0.0';
const log = await git.log({ from: lastTag, to: 'HEAD' });
let bump = 'none';
for (const c of log.all) {
  if (/BREAKING CHANGE/.test(c.body) || /^\w+(\(.+\))?!:/.test(c.message)) { bump = 'major'; break; }
  if (/^feat(\(.+\))?:/.test(c.message)) bump = 'minor';
  else if (/^fix(\(.+\))?:/.test(c.message) && bump === 'none') bump = 'patch';
}
if (bump === 'none') { console.log('Nothing to release'); process.exit(0); }
const [maj, min, pat] = pkg.version.split('.').map(Number);
const next = bump === 'major' ? `${maj + 1}.0.0` : bump === 'minor' ? `${maj}.${min + 1}.0` : `${maj}.${min}.${pat + 1}`;
if (!argv['dry-run']) {
  pkg.version = next;
  fs.writeFileSync('package.json', JSON.stringify(pkg, null, 2) + '\n');
  await git.addTag(`v${next}`);
}
console.log(`Next version: ${next}`);
```

### Architectural Flaws in Original Code
1. **Versioning policy in a script body:** the Conventional Commits rules cannot be tested without a git repository.
2. **Tooling everywhere:** `yargs`, `simple-git` and `fs` are used in the same flow that decides the bump.
3. **`process.exit` in the middle of logic** makes the flow impossible to reuse from another command.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/version.ts`)
```typescript
export type Bump = 'none' | 'patch' | 'minor' | 'major';

export interface Commit {
  readonly subject: string;
  readonly body: string;
}

const RANK: { readonly [B in Bump]: number } = { none: 0, patch: 1, minor: 2, major: 3 };

export function bumpFor(commit: Commit): Bump {
  if (/BREAKING CHANGE/.test(commit.body) || /^\w+(\(.+\))?!:/.test(commit.subject)) return 'major';
  if (/^feat(\(.+\))?:/.test(commit.subject)) return 'minor';
  if (/^fix(\(.+\))?:/.test(commit.subject)) return 'patch';
  return 'none';
}

export function releaseBump(commits: readonly Commit[]): Bump {
  return commits.map(bumpFor).reduce<Bump>((a, b) => (RANK[b] > RANK[a] ? b : a), 'none');
}

export function nextVersion(current: string, bump: Exclude<Bump, 'none'>): string {
  const [major, minor, patch] = current.split('.').map(Number);
  if (bump === 'major') return `${major + 1}.0.0`;
  if (bump === 'minor') return `${major}.${minor + 1}.0`;
  return `${major}.${minor}.${patch + 1}`;
}
```

